  // Export single quotation as Excel-compatible CSV file
  const handleExportExcel = (quote: Quotation) => {
    try {
      const financials = getQuoteFinancials(quote);
      let csvContent = "\ufeff"; // UTF-8 BOM
      
      // Headers
      csvContent += `å ±åƒ¹å–®è™Ÿ,${quote.id}\r\n`;
      csvContent += `å®¢æˆ¶å§“å,${quote.customerName}\r\n`;
      csvContent += `è¯çµ¡é›»è©±,${quote.phone}\r\n`;
      csvContent += `è£ä¿®åœ°å€,${quote.address}\r\n`;
      csvContent += `ç·¨è£½æ—¥æœŸ,${quote.date}\r\n`;
      csvContent += `ç›®å‰ç‹€æ…‹,${getStatusLabel(quote.status)}\r\n`;
      csvContent += `ç‰ˆæœ¬æ¨™è¨˜,${quote.version}\r\n\r\n`;
      
      csvContent += "å·¥ç¨‹é …ç›®åˆ†é¡,é …ç›®åç¨±,å–®ä½,æ•¸é‡,å–®åƒ¹,å°è¨ˆ (HKD),å‚™è¨»èªªæ˜\r\n";
      
      // Group and output
      const quoteCategories = getQuotationCategories(quote, categories);
      quoteCategories.forEach(cat => {
        const items = quote.items.filter(i => i.category === cat);
        if (items.length > 0) {
          items.forEach(i => {
            const rowPrice = i.unitPrice;
            const rowSub = i.quantity * rowPrice;
            const cleanName = i.name.replace(/,/g, 'ï¼Œ');
            const cleanRemark = i.remark.replace(/,/g, 'ï¼Œ').replace(/\n/g, ' ï¼› ');
            csvContent += `${cat},${cleanName},${i.unit},${i.quantity},${rowPrice},${rowSub},${cleanRemark}\r\n`;
          });
        }
      });

      if (quote.enableDiscounts && quote.discounts && quote.discounts.length > 0) {
        csvContent += `,,,,,åŸåƒ¹å°è¨ˆ,${financials.subtotal}\r\n`;
        quote.discounts.forEach(d => {
          const discountItemName = d.targetItemId ? (quote.items.find(i => i.id === d.targetItemId || i.name === d.targetItemId)?.name || d.targetItemId) : 'æ•´é«”åˆç´„';
          csvContent += `,,,,,ç‰¹åˆ¥æŠ˜æ‰£ (${discountItemName}),-${d.amount}\r\n`;
        });
      } else if (quote.discount > 0) {
        const discountItemName = quote.discountTargetItemId ? (quote.items.find(i => i.id === quote.discountTargetItemId || i.name === quote.discountTargetItemId)?.name || quote.discountTargetItemId) : 'æ•´é«”åˆç´„';
        csvContent += `,,,,,åŸåƒ¹å°è¨ˆ,${financials.subtotal}\r\n`;
        csvContent += `,,,,,ç‰¹åˆ¥æŠ˜æ‰£ (${discountItemName}),-${quote.discount}\r\n`;
      }
      csvContent += `,,,,,åˆè¨ˆæ·¨å€¼,${financials.grandTotal}\r\n`;
      
      // Payment breakdown
      csvContent += `\r\nè¨‚é‡‘åˆ†é…è¦åŠƒ (${quote.depositPercent}%),${financials.depositVal}\r\n`;
      csvContent += `ä¸­æœŸå·¥ç¨‹æ¬¾åˆ†é… (${quote.progressPercent}%),${financials.progressVal}\r\n`;
      csvContent += `å®Œå·¥çµç®—å°¾æ¬¾ (${quote.balancePercent}%),${financials.balanceVal}\r\n`;

      // Append Variation Orders (å¾ŒåŠ å·¥ç¨‹) if present
      const migratedQuote = migrateQuotation(quote);
      if (migratedQuote.variationOrders && migratedQuote.variationOrders.length > 0) {
        migratedQuote.variationOrders.forEach((vo, idx) => {
          if (vo.items && vo.items.length > 0) {
            csvContent += `\r\nã€${vo.title || `å¾ŒåŠ å·¥ç¨‹ ${idx + 1}`} æ˜ç´°ã€‘\r\n`;
            csvContent += "å·¥ç¨‹é …ç›®åˆ†é¡,é …ç›®åç¨±,å–®ä½,æ•¸é‡,å–®åƒ¹,å°è¨ˆ (HKD),å‚™è¨»èªªæ˜\r\n";
            vo.items.forEach(i => {
              const cleanName = i.name.replace(/,/g, 'ï¼Œ');
              const cleanRemark = (i.remark || '').replace(/,/g, 'ï¼Œ').replace(/\n/g, ' ï¼› ');
              csvContent += `${i.category || 'å¾ŒåŠ å·¥ç¨‹'},${cleanName},${i.unit},${i.quantity},${i.unitPrice},${i.quantity * i.unitPrice},${cleanRemark}\r\n`;
            });
            if (vo.discount > 0) {
              csvContent += `,,,,,å¾ŒåŠ å·¥ç¨‹æŠ˜è®“,-${vo.discount}\r\n`;
            }
          }
        });
      }

      const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
      const url = URL.createObjectURL(blob);
      const link = document.createElement("a");
      link.setAttribute("href", url);
      
      const internalNo = quote.internalNumber || quote.id;
      const address = quote.address || "ç„¡åœ°å€";
      const todayStr = new Date().toISOString().split('T')[0];
      const filename = `${internalNo} - ${address} - ${todayStr}.csv`;
      
      link.setAttribute("download", filename);
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);
      showToast('å ±åƒ¹å–® Excel / CSV è¡¨æ ¼å·²æˆåŠŸä¸‹è¼‰');
    } catch (err) {
      showToast('å°å‡º Excel è¡¨æ ¼å¤±æ•—ï¼', 'error');
      console.error(err);
    }
  };

